app.MapGet("/api/users", async (string search, AppDbContext db) =>
{
    // DANGEROUS: user input is concatenated into SQL
    var sql = $"SELECT * FROM Users WHERE Name = '{search}' AND IsActive = 1";
    var users = await db.Users.FromSqlRaw(sql).ToListAsync();
    return Results.Ok(users);
});

app.MapGet("/api/users", async (string search, IDbConnection db) =>
{
    const string sql = @"
        SELECT * FROM Users
        WHERE Name = @Search AND IsActive = 1
    ";

    var users = await db.QueryAsync<User>(sql, new { Search = search });
    return Results.Ok(users);
});

app.MapGet("/api/users", async (string search, AppDbContext db) =>
{
    var users = await db.Users
        .Where(u => u.Name.Contains(search) && u.IsActive)
        .ToListAsync();

    return Results.Ok(users);
});

CREATE PROCEDURE GetActiveUsers
    @Search NVARCHAR(100)
AS
BEGIN
    SELECT * FROM Users
    WHERE Name LIKE '%' + @Search + '%'
      AND IsActive = 1;
END

// Calling from C#:
var users = await db.QueryAsync<User>(
    "GetActiveUsers",
    new { Search = search },
    commandType: CommandType.StoredProcedure);
